extern vec2 texelSize;
extern vec4 outlineColor;
extern float threshold;
// Optional radial mask to suppress inner-hole edges
extern number u_useRadMask; // 0 or 1
extern vec2 u_center;       // texture coords 0..1
extern float u_innerRadius; // texture coord units
vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc){
  float a0 = Texel(tex, tc).a;
  if (a0 > threshold) {
    float a1 = Texel(tex, tc + vec2(texelSize.x, 0.0)).a;
    float a2 = Texel(tex, tc + vec2(-texelSize.x, 0.0)).a;
    float a3 = Texel(tex, tc + vec2(0.0, texelSize.y)).a;
    float a4 = Texel(tex, tc + vec2(0.0, -texelSize.y)).a;
    float a5 = Texel(tex, tc + vec2(texelSize.x, texelSize.y)).a;
    float a6 = Texel(tex, tc + vec2(-texelSize.x, texelSize.y)).a;
    float a7 = Texel(tex, tc + vec2(texelSize.x, -texelSize.y)).a;
    float a8 = Texel(tex, tc + vec2(-texelSize.x, -texelSize.y)).a;
    float neighborMin = min(min(min(a1,a2),min(a3,a4)), min(min(a5,a6),min(a7,a8)));
    if (neighborMin <= threshold) {
      if (u_useRadMask > 0.5) {
        float r = length(tc - u_center);
        if (r < u_innerRadius) return vec4(0.0);
      }
      return outlineColor;
    }
  }
  return vec4(0.0,0.0,0.0,0.0);
}


extern vec2 texelSize;
extern vec4 outlineColor;
extern float threshold;
extern number u_usePrism; 
extern number u_time;     
extern number u_targetDpi;
// UV rect for atlas clamping: x, y, width, height (0..1)
extern vec4 u_frameUV;     
// Radial mask (optional)
extern number u_useRadMask; 
extern vec2 u_center;       
extern float u_innerRadius; 
// Outer-only gating (optional)
extern number u_useOuterOnly; 
extern float u_step;          
// Ring exclusion mask in SCREEN space
extern number u_useRingMask;  
extern vec2   u_ringCenter;   
extern float  u_ringInner;    
extern float  u_ringOuter;    
extern number u_selectedSweep;
extern vec2 u_sweepCenter;

vec4 safeTexel(Image tex, vec2 tc) {
  // Use a small epsilon to avoid floating point precision issues at bounds
  float eps = 0.00001;
  vec4 color = Texel(tex, clamp(tc, u_frameUV.xy, u_frameUV.xy + u_frameUV.zw));
  vec2 mask = step(u_frameUV.xy - eps, tc) * step(tc, u_frameUV.xy + u_frameUV.zw + eps);
  return color * (mask.x * mask.y);
}

vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc){
  vec2 logicalSc = sc / max(1.0, u_targetDpi);
  float a0 = safeTexel(tex, tc).a;
  if (a0 <= threshold) {
    float a1 = safeTexel(tex, tc + vec2(texelSize.x, 0.0)).a;
    float a2 = safeTexel(tex, tc + vec2(-texelSize.x, 0.0)).a;
    float a3 = safeTexel(tex, tc + vec2(0.0, texelSize.y)).a;
    float a4 = safeTexel(tex, tc + vec2(0.0, -texelSize.y)).a;
    float a5 = safeTexel(tex, tc + vec2(texelSize.x, texelSize.y)).a;
    float a6 = safeTexel(tex, tc + vec2(-texelSize.x, texelSize.y)).a;
    float a7 = safeTexel(tex, tc + vec2(texelSize.x, -texelSize.y)).a;
    float a8 = safeTexel(tex, tc + vec2(-texelSize.x, -texelSize.y)).a;
    float neighbor = max(max(max(a1,a2),max(a3,a4)), max(max(a5,a6),max(a7,a8)));
    if (neighbor > threshold) {
      if (u_useRadMask > 0.5) {
        float r = length(tc - u_center);
        if (r < u_innerRadius) return vec4(0.0);
      }
      if (u_useOuterOnly > 0.5) {
        vec2 dir = tc - u_center;
        float len = length(dir);
        if (len > 0.0001) {
          vec2 stepv = dir * (u_step / len);
          float aOut = safeTexel(tex, tc + stepv).a;
          if (aOut > threshold) return vec4(0.0);
        }
      }
      if (u_useRingMask > 0.5) {
        float d = length(logicalSc - u_ringCenter);
        if (d >= u_ringInner && d <= u_ringOuter) return vec4(0.0);
      }
      if (u_usePrism > 0.5) {
        float p = (logicalSc.x * 0.06 + logicalSc.y * 0.04) + u_time * 1.5;
        float pr = 0.70 + 0.30 * sin(p + 0.0);
        float pg = 0.65 + 0.35 * sin(p + 2.1);
        float pb = 0.75 + 0.25 * sin(p + 4.2);
        vec3 rgb = clamp(vec3(pr, pg, pb), 0.0, 1.0);
        if (u_selectedSweep > 0.5) {
          vec2 d = tc - u_sweepCenter;
          float angle = atan(d.y, d.x) / 6.2831853 + 0.5;
          float sweepPos = fract(angle - u_time * 0.55);
          float sweep = 1.0 - smoothstep(0.0, 0.16, abs(sweepPos - 0.5));
          rgb = mix(rgb, vec3(1.0, 0.95, 0.72), sweep * 0.75);
        }
        return vec4(rgb, outlineColor.a);
      }
      if (u_selectedSweep > 0.5) {
        vec2 d = tc - u_sweepCenter;
        float angle = atan(d.y, d.x) / 6.2831853 + 0.5;
        float sweepPos = fract(angle - u_time * 0.55);
        float sweep = 1.0 - smoothstep(0.0, 0.16, abs(sweepPos - 0.5));
        vec3 rgb = mix(outlineColor.rgb, vec3(1.0, 0.92, 0.58), sweep * 0.85);
        float alpha = min(1.0, outlineColor.a + sweep * 0.25);
        return vec4(rgb, alpha);
      }
      return outlineColor;
    }
  }
  return vec4(0.0,0.0,0.0,0.0);
}

extern number u_time;     // seconds
extern number u_alpha;    // overlay opacity (0..1), masked by sprite alpha
extern vec2   u_dir;      // normalized drift direction in UV space
extern number u_cycle;    // seconds per full color cycle (3..5)
extern number u_scale;    // spatial scale of pattern
extern number u_grainScale; // grain density (screen-space)
extern number u_grainAmp; // grain strength (0..1)
extern number u_filmFreq; // thin-film interference frequency
extern number u_filmAmp;  // thin-film amplitude
extern number u_specular; // metallic/specular band strength
extern number u_fresnelPow; // fresnel shaping power (>=1)
extern vec4   u_frameUV;  // {minU, minV, sizeU, sizeV}; for full images use {0,0,1,1}
extern number u_colorGain; // overall color gain (1.0 = neutral)
extern number u_saturation; // color saturation multiplier (1.0 = neutral)
extern number u_mixBP;    // mix factor between wide and blue-purple palette (0..1)

vec3 palette(float x, vec3 a, vec3 b, vec3 c, vec3 d){
  return a + b * cos(6.28318 * (c * x + d));
}
float hash(vec2 p){
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}
vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc){
  // IMPORTANT: treat input as an ALPHA MASK (text canvas). Only alpha matters.
  float maskA = Texel(tex, tc).a;
  if (maskA <= 0.001) return vec4(0.0);
  float alpha = clamp(u_alpha, 0.0, 1.0) * maskA;
  if (alpha <= 0.0) return vec4(0.0);

  vec2 dir = u_dir;
  if (length(dir) < 0.001) dir = vec2(0.94, 0.34);
  else dir = normalize(dir);
  vec2 ortho = vec2(-dir.y, dir.x);
  vec2 tcL = tc;
  if (u_frameUV.z > 0.0 && u_frameUV.w > 0.0){
    tcL = (tc - u_frameUV.xy) / u_frameUV.zw;
    tcL = clamp(tcL, 0.0, 1.0);
  }
  float u = dot(tcL, dir) * u_scale + (u_time / max(u_cycle, 0.001));
  float v = dot(tcL, ortho) * u_scale;
  float grainLine = abs(sin(dot(tcL, ortho) * u_grainScale));
  float grainNoise = hash(tcL * 97.0 + vec2(13.3,7.7));
  float grain = mix(grainLine, grainNoise, 0.25);
  float film = u_filmAmp * (0.5 + 0.5 * sin(6.28318 * (u * u_filmFreq + grainNoise * 0.15)));
  float x = u + film;
  vec3 colBP = palette(x,
    vec3(0.55, 0.50, 0.58),
    vec3(0.25, 0.20, 0.28),
    vec3(1.00, 1.00, 1.00),
    vec3(0.10, 0.43, 0.78)
  );
  vec3 colWide = palette(u, vec3(0.52), vec3(0.12), vec3(1.0), vec3(0.00, 0.33, 0.66));
  vec3 foil = mix(colWide, colBP, clamp(u_mixBP, 0.0, 1.0));
  float band = 0.5 + 0.5 * sin(6.28318 * (u * 0.05 + v * 0.03));
  float fres = pow(0.5 + 0.5 * sin(6.28318 * v * 0.10), max(1.0, u_fresnelPow));
  float spec = u_specular * band * (0.2 + 0.8 * fres) * 0.15;
  float grainMul = 1.0 + u_grainAmp * (grain * 0.15 - 0.03);
  vec3 outRGB = foil * grainMul + spec;
  float Y = dot(outRGB, vec3(0.2126, 0.7152, 0.0722));
  outRGB = mix(vec3(Y), outRGB, max(0.0, u_saturation));
  outRGB *= max(0.0, u_colorGain);
  // Premultiply to guarantee no color outside the mask.
  return vec4(outRGB * alpha, alpha);
}

extern number u_time;     // seconds
extern number u_alpha;    // overlay opacity (0..1), masked by sprite alpha
extern vec2   u_dir;      // normalized drift direction in UV space
extern number u_cycle;    // seconds per full color cycle (3..5)
extern number u_scale;    // spatial scale of pattern
extern number u_grainScale; // grain density (screen-space)
extern number u_grainAmp; // grain strength (0..1)
extern number u_filmFreq; // thin-film interference frequency
extern number u_filmAmp;  // thin-film amplitude
extern number u_specular; // metallic/specular band strength
extern number u_fresnelPow; // fresnel shaping power (>=1)
extern vec4   u_frameUV;  // {minU, minV, sizeU, sizeV}; for full images use {0,0,1,1}
extern number u_colorGain; // overall color gain (1.0 = neutral)
extern number u_saturation; // color saturation multiplier (1.0 = neutral)
extern number u_mixBP;    // mix factor between wide and blue-purple palette (0..1)

vec3 palette(float x, vec3 a, vec3 b, vec3 c, vec3 d){
  return a + b * cos(6.28318 * (c * x + d));
}
float hash(vec2 p){
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}
vec4 effect(vec4 color, Image tex, vec2 tc, vec2 sc){
  vec4 base = Texel(tex, tc) * color; // includes source alpha
  if (base.a <= 0.001) return vec4(0.0);
  float alpha = clamp(u_alpha, 0.0, 1.0) * base.a;
  if (alpha <= 0.0) return vec4(0.0);

  vec2 dir = u_dir;
  if (length(dir) < 0.001) dir = vec2(0.94, 0.34);
  else dir = normalize(dir);
  vec2 ortho = vec2(-dir.y, dir.x);
  vec2 tcL = tc;
  if (u_frameUV.z > 0.0 && u_frameUV.w > 0.0){
    tcL = (tc - u_frameUV.xy) / u_frameUV.zw;
    tcL = clamp(tcL, 0.0, 1.0);
  }
  float u = dot(tcL, dir) * u_scale + (u_time / max(u_cycle, 0.001));
  float v = dot(tcL, ortho) * u_scale;
  float grainLine = abs(sin(dot(tcL, ortho) * u_grainScale));
  float grainNoise = hash(tcL * 97.0 + vec2(13.3,7.7));
  float grain = mix(grainLine, grainNoise, 0.25);
  float film = u_filmAmp * (0.5 + 0.5 * sin(6.28318 * (u * u_filmFreq + grainNoise * 0.15)));
  float x = u + film;
  vec3 colBP = palette(x,
    vec3(0.55, 0.50, 0.58),
    vec3(0.25, 0.20, 0.28),
    vec3(1.00, 1.00, 1.00),
    vec3(0.10, 0.43, 0.78)
  );
  vec3 colWide = palette(u, vec3(0.52), vec3(0.12), vec3(1.0), vec3(0.00, 0.33, 0.66));
  vec3 foil = mix(colWide, colBP, clamp(u_mixBP, 0.0, 1.0));
  float band = 0.5 + 0.5 * sin(6.28318 * (u * 0.05 + v * 0.03));
  float fres = pow(0.5 + 0.5 * sin(6.28318 * v * 0.10), max(1.0, u_fresnelPow));
  float spec = u_specular * band * (0.2 + 0.8 * fres) * 0.15;
  float grainMul = 1.0 + u_grainAmp * (grain * 0.15 - 0.03);
  vec3 outRGB = foil * grainMul + spec;
  // Apply saturation boost and color gain (icon-sized legibility)
  float Y = dot(outRGB, vec3(0.2126, 0.7152, 0.0722));
  outRGB = mix(vec3(Y), outRGB, max(0.0, u_saturation));
  outRGB *= max(0.0, u_colorGain);
  return vec4(outRGB, alpha);
}

vec4 effect(vec4 color, Image texture, vec2 texture_coords, vec2 screen_coords){
  vec4 t = Texel(texture, texture_coords);
  return vec4(color.rgb, t.a * color.a);
}
